import { createHmac, timingSafeEqual } from 'crypto'

export interface ConnectorConfig {
  shopifyClientSecret: string
  slackBotToken: string
  slackChannelId: string
  fetch?: typeof fetch
}

export interface ShopifyOrderPayload {
  id: number
  name: string
  email: string
  total_price: string
  currency: string
  line_items: Array<{
    title: string
    quantity: number
    price: string
  }>
}

export interface SlackMessageResponse {
  ok: boolean
  channel: string
  ts: string
  message: {
    text: string
    username: string
    bot_id: string
  }
}

export interface HandleResult {
  slackMessageTs: string
  slackChannelId: string
}

function formatOrderSummary(order: ShopifyOrderPayload): string {
  const itemsSummary = order.line_items
    .map((item) => `${item.quantity} x ${item.title}`)
    .join(', ')
  const total = `$${order.total_price} ${order.currency}`
  return `New order ${order.name} from ${order.email}: ${itemsSummary} - Total: ${total}`
}

async function verifyHmacSignature(
  rawBody: string,
  signatureHeader: string | null,
  secret: string,
): Promise<void> {
  if (!signatureHeader) {
    throw new Error('Missing X-Shopify-Hmac-Sha256 header')
  }

  const encoder = new TextEncoder()
  const keyData = encoder.encode(secret)
  const messageData = encoder.encode(rawBody)

  const cryptoKey = await crypto.subtle.importKey(
    'raw',
    keyData,
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign'],
  )

  const signature = await crypto.subtle.sign('HMAC', cryptoKey, messageData)
  const expectedSignature = Buffer.from(signature).toString('base64')

  const providedSignature = signatureHeader.trim()
  if (!timingSafeEqual(providedSignature, expectedSignature)) {
    throw new Error('Invalid HMAC signature')
  }
}

export async function handle(
  payload: ShopifyOrderPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  if (!payload.id) throw new Error('Missing required field: id')
  if (!payload.name) throw new Error('Missing required field: name')
  if (!payload.email) throw new Error('Missing required field: email')
  if (!payload.total_price) throw new Error('Missing required field: total_price')
  if (!payload.currency) throw new Error('Missing required field: currency')
  if (!payload.line_items || !Array.isArray(payload.line_items)) {
    throw new Error('Missing required field: line_items')
  }

  const rawBody = JSON.stringify(payload)
  const hmacHeader = 'X-Shopify-Hmac-Sha256'
  const signature = fetchImpl[hmacHeader] ?? null

  await verifyHmacSignature(rawBody, signature, config.shopifyClientSecret)

  const text = formatOrderSummary(payload)

  const slackResponse = await fetchImpl('https://slack.com/api/chat.postMessage', {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.slackBotToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      channel: config.slackChannelId,
      text,
    }),
  })

  if (!slackResponse.ok) {
    const errorText = await slackResponse.text().catch(() => 'Unknown error')
    throw new Error(
      `Slack API error: ${slackResponse.status} ${slackResponse.statusText} at https://slack.com/api/chat.postMessage - ${errorText}`,
    )
  }

  const slackData = (await slackResponse.json()) as SlackMessageResponse

  if (!slackData.ok) {
    throw new Error('Slack API returned ok: false')
  }

  return {
    slackMessageTs: slackData.ts,
    slackChannelId: slackData.channel,
  }
}

