    throw new Error(
      `Slack API error: ${slackResponse.status} ${slackResponse.statusText} at https://slack.com/api/chat.postMessage - ${errorText}`,
    )
  }

  const slackData = (await slackResponse.json()) as SlackMessageResponse

  if (!slackData.ok) {
    throw new Error('Slack API returned ok: false')
  }

  return {
    slackMessageTs: slackData.ts,
    slackChannelId: slackData.channel,
  }
}

